Method.Implementation:
set ctrlNum = 1
set ctlNm = $ZSTRIP(ConfigName, "<>W")_","_$ZSTRIP(sender, "<>W")_","_$ZSTRIP(receiver, "<>W")

if ($DATA(^[$NAMESPACE]X12ControlNumber(ctlNm)) '= 0)
{
	SET ctrlNum = ^[$NAMESPACE]X12ControlNumber(ctlNm) + 1
}
set ^[$NAMESPACE]X12ControlNumber(ctlNm) = ctrlNum
return ctrlNum
